renderHTML:
__ht__function(data, gv, cache) {var msgdata = [
			["1号消息", "2023-01-01 14:43"],
			["2号消息", "2023-01-02 14:43"],
			["3号消息", "2023-01-03 14:43"],
			["4号消息", "2023-01-04 14:43"],
			["5号消息", "2023-01-05 14:43"],
			["6号消息", "2023-01-06 14:43"]
		];
if (!cache.htmlView) {

        var div = cache.htmlView = document.createElement('div');
        div.style.position = 'absolute';
        div.style.overflow = 'hidden';
        div.style.setProperty("box-sizing", "border-box", null);
        div.style.setProperty("-moz-box-sizing", "border-box", null);

        var boxallbefStyle= document.createElement('style');
        boxallbefStyle.type = "text/css";
        boxallbefStyle.appendChild(document.createTextNode('.boxall:{border: 0px solid rgba(25, 186, 139, .17);padding: 0px 0px 0px;background-size: 100% auto;position: relative;margin-bottom: 0px;z-index: 10;width:100%;}'));
        boxallbefStyle.appendChild(document.createTextNode('.boxall:before,.boxall:after {position: absolute;width:12px;height:12px;border-top: 2px solid #02a6b5;top: 0;}'));
        boxallbefStyle.appendChild(document.createTextNode('.boxall:before,.boxfoot:before {border-left: 2px solid #02a6b5;left: 0;}'));
        boxallbefStyle.appendChild(document.createTextNode('.boxall:after,.boxfoot:after {border-right: 2px solid #02a6b5;right: 0;}'));
        boxallbefStyle.appendChild(document.createTextNode('.boxfoot:{position: absolute;bottom: 0;width: 100%;left: 0;}'));
        boxallbefStyle.appendChild(document.createTextNode('.boxfoot:before,.boxfoot:after {position: absolute;width:12px;height:12px;border-bottom: 2px solid #02a6b5;bottom: 0;}'));
        
        boxallbefStyle.appendChild(document.createTextNode('.wrap li {height:40px;text-indent: 28px;margin-bottom: 5px;border-bottom: 1px solid rgba(25, 186, 139, .17);}'));
        boxallbefStyle.appendChild(document.createTextNode('.wrap li p:first-child {font-size: 16px;color: #12d6d6;}'));
        boxallbefStyle.appendChild(document.createTextNode('.wrap li p:last-child {font-size: 10px;color: rgba(255, 255, 255, .5);}'));
        cache.htmlView.appendChild(boxallbefStyle); 


        var boxalldiv = document.createElement('div');
        boxalldiv.className = 'boxall';
        cache.htmlView.appendChild(boxalldiv); 


        var alltitle = cache.htmltitle = document.createElement('div');
        alltitle.style.color = '#fff';
        alltitle.style.fontSize = '28px';
        alltitle.style.textAlign = 'center';
        alltitle.style.lineHeight = '72px';
        alltitle.style.borderBottom = '1px solid rgba(255, 255, 255, .2)';
        //alltitle.innerText = "消息列表";
        boxalldiv.appendChild(alltitle); 

        var wrap = cache.htmlwrap = document.createElement('div');
        wrap.className = 'wrap';
        wrap.style.overflow = 'hidden';
        wrap.style.height = '305px';
        boxalldiv.appendChild(wrap); 

        var boxfoot = document.createElement('div');
        boxfoot.className = 'boxfoot';
        boxalldiv.appendChild(boxfoot); 

        data.div = div;
        div.addEventListener('mousedown', function(e){e.preventDefault();}, false);
        div.layoutHTML = function() {
            gv.layoutHTML(data, div);
            //if(data.a('div.debug')) console.log('Div is layout');
        };
        div.onHTMLAdded = function() {
            //if(data.a('div.debug')) console.log('Div is added');
        };
        div.onHTMLRemoved = function() {
            //if(data.a('div.debug')) console.log('Div is removed');
        };

    }

    cache.htmlView.style.color = data.a('div.color');
    cache.htmlView.style.background = data.a('div.background');
    cache.htmltitle.hidden=!data.a('div.title');

    if(data.a('div.title'))
        cache.htmltitle.innerText = data.a('div.title');

    if(data.a('div.msgdata')&&data.a('div.msgdata')!=msgdata)
    {
        cache.htmlwrap.innerHTML="";
        msgdata=data.a('div.msgdata');
        var listul = document.createElement('ul');
        listul.id="ullli";
		for (var i = 0; i < msgdata.length; i++) {
            var listli = document.createElement('li');

            listul.appendChild(listli); 

            var p1= document.createElement('p');
            p1.innerText=msgdata[i][0];
            listli.appendChild(p1); 

            var p2= document.createElement('p');
            p2.innerText=msgdata[i][1];
            listli.appendChild(p2); 
		}
        cache.htmlwrap.appendChild(listul); 
}

    return cache.htmlView;}
